import {validateRequestLinks} from './ata-logic.js';
import {Store} from './store.js';
import {escape as esc, normalize, number, toast} from './utils.js';
import {icon} from './icons.js';
import {open, close} from './modals.js';
import {remaining, receiptStatus, groupRows, receiveBatch} from './request-logic.js';
const productDescription=text=>`<details class="request-description"><summary><span class="description-preview">${esc(text)}</span><span class="description-more">Mais</span><span class="description-less">Menos</span></summary><p>${esc(text)}</p></details>`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
const historyMarkup=rows=>{const entries=rows.flatMap(r=>(r.receipts||[]).map(h=>({...h,product:r.product,unit:r.unit}))).sort((a,b)=>b.recordedAt.localeCompare(a.recordedAt));return entries.length?`<details class="receipt-history"><summary>Histórico de recebimentos (${entries.length})</summary>${entries.map(h=>`<p>${esc(h.date)} · ${number(h.quantity)} ${esc(h.unit)} de ${esc(h.product)}${h.note?' · '+esc(h.note):''}</p>`).join('')}</details>`:''};
const field=(name,label,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required maxlength="150" ${extra} data-testid="field-${name}"></label>`;
const error=message=>document.getElementById('request-error').textContent=message;
export function requestEditor(record,onSave){
  const originals=record?Store.data.requests.filter(r=>(r.groupId||r.id)===(record.groupId||record.id)):[];
  const first=originals[0]||{},locked=originals.some(r=>r.received>0);
  let items=originals.map(r=>({...r})),searchPage=1;
  let selectedAta=Store.data.atas.find(a=>a.id===first.ataId||a.number===first.ata)?.id||'';
  open(record?'Editar solicitação':'Nova solicitação',`<form id="request-form"><div class="modal-body"><div class="editor-intro"><p>Selecione a ATA e o setor. Depois, adicione os materiais e suas quantidades.</p><span class="step-label">1. Dados da solicitação</span></div><div class="form-grid request-meta"><label class="field">ATA de Registro de Preços<select name="ataId" required ${locked?'disabled':''} data-testid="field-ata"><option value="">Selecione uma ATA cadastrada</option>${Store.data.atas.map(a=>`<option value="${esc(a.id)}" ${a.id===selectedAta?'selected':''}>${esc(a.number)} · ${esc(a.supplier)}</option>`).join('')}</select></label><label class="field">Setor participante<select name="sector" required ${locked?'disabled':''} data-testid="field-sector"></select></label>${field('date','Data da solicitação',first.date||today(),'date')}${field('responsible','Responsável pela solicitação',first.responsible)}${field('ramal','Contato / Ramal',first.ramal,'text','inputmode="tel"')}<div class="field ata-context" id="ata-context"></div></div><p id="request-error" role="alert" class="form-error"></p><div class="request-columns"><section class="editor-section request-catalog"><div class="section-heading"><h3>Produtos disponíveis</h3><span class="step-label">2. Buscar e adicionar</span></div><div class="request-search"><label class="field">Busca rápida de produtos<div class="input-wrap">${icon('search')}<input id="product-search" type="search" placeholder="Código ou nome do produto..." autocomplete="off" data-testid="product-search"></div></label><div id="product-results" class="product-results" aria-live="polite"></div><div id="product-pages" class="picker-pages"></div></div></section><section class="editor-section request-selection"><div class="section-heading"><h3>Produtos da solicitação <span id="item-count" class="count-pill">0</span></h3><span class="step-label">3. Informar quantidades</span></div><div id="request-items"></div></section></div></div><div class="modal-footer"><span class="footer-hint">As pendências serão geradas ao salvar a solicitação.</span><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary" type="submit" data-testid="save-request">${icon('check')} Salvar solicitação</button></div></form>`);
  document.getElementById('modal').classList.add('request-dialog');
  const form=document.getElementById('request-form');
  function sectorOptions(preferred=''){
    const ata=Store.data.atas.find(a=>a.id===selectedAta),available=Store.data.sectors.filter(s=>ata?.sectorIds?.includes(s.id));
    form.elements.sector.innerHTML='<option value="">'+(ata?(available.length?'Selecione um setor participante':'ATA sem setores: configure o cadastro'):'Escolha uma ATA primeiro')+'</option>'+available.map(s=>`<option value="${esc(s.name)}" ${s.name===preferred?'selected':''}>${esc(s.name)}</option>`).join('');
    document.getElementById('ata-context').innerHTML=ata?`<span>Participação na ATA</span><strong>${available.length} setor(es) · ${(ata.productIds||[]).length} produto(s)</strong>`:'<span>Catálogo por ATA</span><strong>Escolha uma ATA para começar</strong>';
    document.getElementById('product-search').disabled=!ata;
  }
  function renderItems(){
    document.getElementById('item-count').textContent=items.length;
    document.getElementById('request-items').innerHTML=items.length?items.map((r,i)=>`<article class="selected-product" data-testid="selected-product"><div class="selected-product-info"><span class="request-product-code">${esc(r.code)}</span>${productDescription(r.product)}<small>Unidade: ${esc(r.unit)}${r.received?` · ${number(r.received)} recebido(s)`:''}</small></div><label class="field quantity-field">Quantidade<input class="quantity-input" type="number" min="${Math.max(1,r.received||0)}" step="1" value="${r.quantity}" data-quantity="${i}" aria-label="Quantidade de ${esc(r.product)}" required data-testid="item-quantity"></label><button type="button" class="icon-btn" data-remove="${i}" aria-label="Remover ${esc(r.product)}" ${r.received?'disabled title="Item com recebimento registrado"':''}>${icon('trash')}</button></article>`).join(''):`<div class="empty request-empty">${icon('box')}<strong>Sua lista começa aqui</strong><p>Adicione os produtos da ATA ao lado e informe a quantidade de cada um.</p></div>`;
    document.querySelectorAll('[data-quantity]').forEach(el=>el.oninput=()=>{items[Number(el.dataset.quantity)].quantity=Number(el.value)});
    document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{items.splice(Number(el.dataset.remove),1);renderItems();renderSearch()});
  }
  function renderSearch(){
    const ata=Store.data.atas.find(a=>a.id===selectedAta),query=normalize(document.getElementById('product-search').value.trim());
    const matches=Store.data.products.filter(p=>ata?.productIds?.includes(p.id)&&(!query||normalize(p.code+' '+p.product).includes(query)));
    const pages=Math.max(1,Math.ceil(matches.length/5));searchPage=Math.min(searchPage,pages);
    const container=document.getElementById('product-results');
    container.innerHTML=matches.length?`<small class="search-count">${matches.length} produto(s) nesta busca</small>${matches.slice((searchPage-1)*5,searchPage*5).map(p=>`<article class="product-result request-catalog-item"><div class="request-catalog-info"><span class="request-product-code">${esc(p.code)}</span>${productDescription(p.product)}<small>Unidade: ${esc(p.unit)}</small></div><button type="button" class="btn" data-add="${esc(p.id)}" ${items.some(i=>i.code===p.code)?'disabled':''} data-testid="add-product">${items.some(i=>i.code===p.code)?'✓ Adicionado':'+ Adicionar'}</button></article>`).join('')}`:`<p class="search-count">${!ata?'Selecione uma ATA para consultar seus produtos.':!ata.productIds.length?'Esta ATA ainda não tem produtos. Vincule-os no cadastro da ATA, no catálogo ou na importação.':'Nenhum produto encontrado. Tente outro código ou nome.'}</p>`;
    const pager=document.getElementById('product-pages');pager.innerHTML=matches.length?`<button type="button" class="btn" id="search-prev" ${searchPage===1?'disabled':''}>‹ Anterior</button><span>${searchPage} de ${pages}</span><button type="button" class="btn" id="search-next" ${searchPage===pages?'disabled':''}>Próxima ›</button>`:'';
    if(matches.length){document.getElementById('search-prev').onclick=()=>{searchPage--;renderSearch()};document.getElementById('search-next').onclick=()=>{searchPage++;renderSearch()}}
    container.querySelectorAll('[data-add]').forEach(button=>button.onclick=()=>{const p=Store.data.products.find(p=>p.id===button.dataset.add);if(!p||!ata.productIds.includes(p.id)||items.some(i=>i.code===p.code))return;items.push({productId:p.id,code:p.code,product:p.product,unit:p.unit,quantity:1,received:0,receipts:[]});renderItems();renderSearch()});
  }
  document.getElementById('product-search').oninput=()=>{searchPage=1;renderSearch()};
  form.elements.ataId.onchange=()=>{if(items.length){form.elements.ataId.value=selectedAta;return error('Remova os produtos da lista antes de trocar a ATA. Itens com recebimentos devem permanecer na ATA original.')}selectedAta=form.elements.ataId.value;searchPage=1;sectorOptions();renderSearch();error('')};
  form.elements.sector.onchange=()=>{const sector=Store.data.sectors.find(s=>s.name===form.elements.sector.value);if(sector){form.elements.responsible.value=sector.responsible||'';form.elements.ramal.value=sector.ramal||''}};
  form.onsubmit=e=>{
    e.preventDefault();const values=Object.fromEntries(new FormData(form));for(const key in values)values[key]=values[key].trim();
    if(locked){values.ataId=selectedAta;values.sector=first.sector}
    if(!values.sector||!values.responsible||!values.ramal||!values.ataId||!values.date)return error('Informe ATA, setor, responsável, ramal e data.');
    if(!items.length)return error('Adicione pelo menos um produto à solicitação.');
    if(items.some(r=>!Number.isSafeInteger(r.quantity)||r.quantity<1||r.quantity<(r.received||0)))return error('As quantidades devem ser inteiras, maiores que zero e não inferiores ao total recebido.');
    let links;try{links=validateRequestLinks(Store.data,values.ataId,values.sector,items)}catch(err){return error(err.message)}
    const groupId=first.groupId||first.id||crypto.randomUUID();
    const requestNumber=first.requestNumber||`SOL-${new Date().getFullYear()}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;
    const updated=items.map(item=>{const product=Store.data.products.find(p=>p.id===item.productId)||Store.data.products.find(p=>p.code===item.code);const row={...item,...values,productId:product.id,sectorId:links.sector.id,ata:links.ata.number,id:item.id||crypto.randomUUID(),groupId,requestNumber};row.status=receiptStatus(row);return row});
    Store.data.requests=[...updated,...Store.data.requests.filter(r=>!originals.some(o=>o.id===r.id))];
    const saved=Store.save();onSave();requestSummary(groupId,onSave);toast(saved?'Solicitação salva. Aviso de pendência gerado.':'Dados nesta sessão. Falha ao salvar no navegador: exporte um backup.');
  };
  sectorOptions(first.sector);renderItems();renderSearch();
}
export function requestSummary(groupId,onSave){
  const rows=Store.data.requests.filter(r=>(r.groupId||r.id)===groupId);if(!rows.length)return;const first=rows[0];const waiting=rows.filter(r=>remaining(r)>0&&r.status!=='Cancelada');
  open('Acompanhamento da solicitação',`<div class="modal-body"><span class="request-number">${esc(first.requestNumber)}</span><h3 class="waiting-title">${waiting.length?`O setor ${esc(first.sector)} aguarda os seguintes produtos`:'Todos os itens foram atendidos ou cancelados'}</h3><p><b>Responsável:</b> ${esc(first.responsible)||'Não informado'} · <b>Ramal:</b> ${esc(first.ramal)||'Não informado'}<br><b>ATA:</b> ${esc(first.ata)||'Não informada'} · <b>Data:</b> ${esc(first.date)}</p><div class="table-scroll"><table><thead><tr><th>Produto</th><th>Solicitado</th><th>Recebido</th><th>Pendente</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.product)}<small class="item-code">${esc(r.code)} · ${esc(r.unit)}${r.status==='Cancelada'?' · Cancelado':''}</small></td><td>${number(r.quantity)}</td><td>${number(r.received||0)}</td><td><b>${r.status==='Cancelada'?'—':number(remaining(r))}</b></td></tr>`).join('')}</tbody></table></div>${historyMarkup(rows)}</div>`,`<div class="modal-footer"><button class="btn" data-close>Fechar</button>${waiting.length?`<button class="btn primary" id="receive-request" data-testid="receive-request">${icon('check')} Registrar recebimento / dar baixa</button>`:''}</div>`);
  document.getElementById('modal').classList.add('request-dialog');
  const button=document.getElementById('receive-request');if(button)button.onclick=()=>receiptEditor(groupId,onSave);
}
export function receiptEditor(groupId,onSave){
  const rows=Store.data.requests.filter(r=>(r.groupId||r.id)===groupId),first=rows[0];if(!first)return;
  const pending=rows.filter(r=>remaining(r)>0&&r.status!=='Cancelada');
  const history=rows.flatMap(r=>(r.receipts||[]).map(receipt=>({...receipt,product:r.product,unit:r.unit}))).sort((a,b)=>b.recordedAt.localeCompare(a.recordedAt));
  open('Registrar recebimento',`<form id="receipt-form"><div class="modal-body"><p><b>${esc(first.sector)}</b> · ${esc(first.requestNumber)}<br>Informe somente as quantidades que chegaram agora. O saldo será atualizado automaticamente.</p><div class="form-grid">${field('receiptDate','Data do recebimento',today(),'date')}<label class="field">Observação (opcional)<input name="note" maxlength="250" placeholder="Ex.: entrega parcial, nota fiscal..."></label></div><div class="table-scroll receipt-table"><table><thead><tr><th>Produto</th><th>Saldo pendente</th><th>Recebido agora</th></tr></thead><tbody>${pending.map(r=>`<tr><td>${esc(r.product)}<small class="item-code">${esc(r.code)} · ${esc(r.unit)}</small></td><td>${number(remaining(r))}</td><td><input class="quantity-input" name="received-${r.id}" data-receive-id="${r.id}" type="number" min="0" max="${remaining(r)}" step="1" value="0" required aria-label="Recebido agora: ${esc(r.product)}" data-testid="received-quantity"></td></tr>`).join('')}</tbody></table></div><p id="request-error" role="alert" class="form-error"></p>${history.length?`<details class="receipt-history"><summary>Histórico de recebimentos (${history.length})</summary>${history.map(h=>`<p>${esc(h.date)} · ${number(h.quantity)} ${esc(h.unit)} de ${esc(h.product)}${h.note?' · '+esc(h.note):''}</p>`).join('')}</details>`:''}</div><div class="modal-footer"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary" type="submit" data-testid="save-receipt" ${pending.length?'':'disabled'}>${icon('check')} Confirmar baixa</button></div></form>`);
  document.getElementById('modal').classList.add('request-dialog');
  document.getElementById('receipt-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const amounts={};pending.forEach(r=>amounts[r.id]=values['received-'+r.id]);try{receiveBatch(rows,amounts,values.receiptDate,values.note.trim())}catch(err){return error(err.message)}const saved=Store.save();onSave();requestSummary(groupId,onSave);toast(saved?'Recebimento registrado. Saldos e pendências atualizados.':'Recebimento nesta sessão. Exporte um backup: falha ao salvar.');};
}
export function waitingPanel(rows){
  const groups=groupRows(rows.filter(r=>r.status!=='Cancelada'&&remaining(r)>0));
  if(!groups.length)return '<section class="data-notice waiting-clear"><strong>✓ Nenhuma pendência de materiais para os filtros atuais.</strong></section>';
  return `<section class="panel waiting-panel" data-testid="waiting-notices"><div class="panel-head"><div><h2>Setores aguardando materiais</h2><p>${groups.length} solicitação(ões) com saldo pendente. Os avisos são atualizados a cada recebimento.</p></div>${icon('clock')}</div><div class="waiting-list">${groups.map((group,index)=>{const first=group[0];return `<details class="waiting-notice waiting-card" data-request-number="${esc(first.requestNumber)}" style="--card-accent:var(--request-accent-${index%4})"><summary><span class="waiting-card-top"><strong>${esc(first.sector)}</strong><span class="waiting-ata-badge">${esc(first.ata)||'Sem ATA'}</span></span><span class="waiting-card-total">${group.length} item(ns) da solicitação</span><span class="waiting-card-expand"><span class="when-closed">Ver itens ⌄</span><span class="when-open">Recolher itens ⌃</span></span></summary><ul class="waiting-items">${group.map(r=>`<li class="waiting-item"><div class="waiting-item-info"><span class="waiting-item-code">${esc(r.code)}</span><span class="waiting-item-description" title="${esc(r.product)}">${esc(r.product)}</span></div><div class="waiting-item-quantity"><small>Solicitado</small><strong>${number(r.quantity)} ${esc(r.unit)}</strong>${r.received?`<small>Pendente: ${number(remaining(r))} ${esc(r.unit)}</small>`:''}</div></li>`).join('')}</ul><button class="btn" data-request-details="${esc(first.groupId||first.id)}" data-testid="notice-details">Ver solicitação / dar baixa ${icon('arrow')}</button></details>`}).join('')}</div></section>`;
}
